@ITreeEutt.itree_head_at_succ
     : forall (E MN : Type -> Type) (A : Type) (n : nat)
         (ot : ITreeDefinition.itreeF E A (ITreeDefinition.itree E A))
         (h : UnifiedFrontier.stable_head E MN A),
       @ITreeEutt.itree_head_at E MN A n ot = @Some (UnifiedFrontier.stable_head E MN A) h ->
       @ITreeEutt.itree_head_at E MN A (S n) ot = @Some (UnifiedFrontier.stable_head E MN A) h

