@ITreeEutt.eutt_head_at
     : forall (E MN : Type -> Type) (A B : Type) (RR : A -> B -> Prop)
         (n : nat) (t : ITreeDefinition.itree E A) (u : ITreeDefinition.itree E B)
         (h : UnifiedFrontier.stable_head E MN A),
       @Eqit.eutt E A B RR t u ->
       @ITreeEutt.itree_head_at E MN A n (@ITreeDefinition.observe E A t) =
       @Some (UnifiedFrontier.stable_head E MN A) h ->
       exists (m : nat) (j : UnifiedFrontier.stable_head E MN B),
         @ITreeEutt.itree_head_at E MN B m (@ITreeDefinition.observe E B u) =
         @Some (UnifiedFrontier.stable_head E MN B) j /\
         @UnifiedFrontier.stable_head_rel E MN A B RR (@ITreeEutt.embedded_eutt E MN A B RR) h j

