@ITreeSourceInterp.itree_interp_before_unfold
     : forall (E F : Type -> Type) (h : forall X : Type, E X -> ITreeDefinition.itree F X)
         (A : Type) (t : ITreeDefinition.itree E A),
       @Eqit.eq_itree F A A (@eq A) (@ITreeSourceInterp.itree_interp_before E F h A t)
         match @ITreeDefinition.observe E A t with
         | @ITreeDefinition.RetF _ _ _ a =>
             {|
               ITreeDefinition._observe := @ITreeDefinition.RetF F A (ITreeDefinition.itree F A) a
             |}
         | @ITreeDefinition.TauF _ _ _ u =>
             {|
               ITreeDefinition._observe :=
                 @ITreeDefinition.TauF F A (ITreeDefinition.itree F A)
                   (@ITreeSourceInterp.itree_interp_before E F h A u)
             |}
         | @ITreeDefinition.VisF _ _ _ X e k =>
             {|
               ITreeDefinition._observe :=
                 @ITreeDefinition.TauF F A (ITreeDefinition.itree F A)
                   (@ITreeDefinition.ITree.bind F X A (h X e)
                      (fun x : X => @ITreeSourceInterp.itree_interp_before E F h A (k x)))
             |}
         end

